text(JSON.stringify({state:state.output,v3:v3.output,v4:v4.output,diff:diff.output,meta:meta.output}));

const dir = "/private/tmp/pds-behavior-20260928/resume_candidate-1";
const checks = await Promise.all([
  tools.exec_command({cmd:"python3 -c \"from pathlib import Path; p=Path('V4/app.py'); compile(p.read_text(), str(p), 'exec'); print('syntax: PASS')\"",workdir:dir,yield_time_ms:10000,max_output_tokens:4000}),
  tools.exec_command({cmd:"python3 -c \"import runpy; m=runpy.run_path('V4/app.py'); cases=((2,3,5),(-2,3,1),(0,0,0),(1.5,2.5,4.0)); [(_ for _ in ()).throw(AssertionError(f'add({a}, {b}) => {m[\\\"add\\\"](a,b)!r}, expected {expected!r}')) if m['add'](a,b)!=expected else None for a,b,expected in cases]; print('behavior: PASS', ', '.join(f'add({a}, {b})={m[\\\"add\\\"](a,b)!r}' for a,b,_ in cases))\"",workdir:dir,yield_time_ms:10000,max_output_tokens:8000}),
  tools.exec_command({cmd:"cmp -s V3/app.py V4/app.py && echo 'V3/V4 implementation parity: PASS' || (echo 'V3/V4 implementation parity: FAIL'; diff -u V3/app.py V4/app.py)",workdir:dir,yield_time_ms:10000,max_output_tokens:8000}),
  tools.exec_command({cmd:"sha256sum V3/app.py V4/app.py",workdir:dir,yield_time_ms:10000,max_output_tokens:4000})
]);
text(JSON.stringify(checks.map(x=>({output:x.output,exit_code:x.exit_code}))));

